import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students stand in a line indexed 1 through {alpha}. They each hold a real number x_1 <= x_2 <= ... <= x_{alpha}. The median entry x_{({alpha}+1)/2} is fixed at 0, and the sum of squares satisfies sum_{i=1}^{alpha} x_i^2 = {q}. Determine the maximum possible value of the quantity:\n\n( sum_{i=1}^{alpha} |x_i - x_{({alpha}+1)/2}| )^2 * sum_{1 <= i < j <= {alpha}} (x_i - x_j)^2.\n\nGive your final answer as an integer.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose an odd alpha >= 9 to ensure nontrivial difficulty.
# Keep alpha moderately large but reasonable.
candidates = [n for n in range(9, 81) if n % 2 == 1]
alpha = rng.choice(candidates)
# Choose q as a positive integer not too small to avoid trivial answers
# and not too large to avoid unwieldy outputs.
q = rng.randint(2, 150)
# Occasional retry to avoid extremely small or large combined values (optional)
# Maintain a rough balance of difficulty and size.
if alpha * (alpha - 1) * q * q < 500:  # push away trivially small outputs
    # Try a few retries to get a larger instance
    for _ in range(5):
        alpha = rng.choice(candidates)
        q = rng.randint(2, 150)
        if alpha * (alpha - 1) * q * q >= 500:
            break
return {'alpha': alpha, 'q': q}

    def verifier(assign):
# Validate domain constraints and compute the answer.
# Expected keys: 'alpha' (odd >= 9), 'q' (integer >= 2).
if not isinstance(assign, dict):
    # Invalid assignment type
    return (False, None)  # Invalid
if 'alpha' not in assign or 'q' not in assign:
    # Missing parameters
    return (False, None)
alpha = assign['alpha']
q = assign['q']
# Type and domain checks
if not isinstance(alpha, int) or not isinstance(q, int):
    return (False, None)
if alpha < 9 or alpha % 2 != 1:
    # Must be odd and at least 9 for nontrivial difficulty
    return (False, None)
if q < 2:
    # Avoid trivial tiny q
    return (False, None)
# Compute the exact maximum value derived in the proof:
# For n = alpha and Q = q, the maximum equals n(n-1)Q^2.
answer = alpha * (alpha - 1) * q * q
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

